// Enums, Models, and Protocols
enum TextSize: CGFloat, CaseIterable {
    case small = 22
    case medium = 30
    case large = 36

    var iconName: String {
        switch self {
        case .small: return "textformat.size.smaller"
        case .medium: return "textformat.size"
        case .large: return "textformat.size.larger"
        }
    }

    mutating func toggle() {
        let allCases = Self.allCases
        guard let currentIndex = allCases.firstIndex(of: self) else { return }
        let nextIndex = (currentIndex + 1) % allCases.count
        self = allCases[nextIndex]
    }
}

