    private func updateAdaptiveState(_ rms: Float) {
        // Update ambient RMS with slow EMA (adapts over ~30s)
        ambientRMS = ambientAlpha * rms + (1.0 - ambientAlpha) * ambientRMS
        // Noise gate = max of absolute floor and adaptive threshold
        effectiveNoiseGate = max(rmsAbsoluteFloor, ambientRMS * rmsAdaptiveMultiplier)

