    private func configureBackgroundAudioSession() {
        let applyConfiguration = { [weak self] in
            guard let self = self else { return }
            Logger.log("Configuring background audio session")

            // End any existing background task
            if self.backgroundTask != .invalid {
                UIApplication.shared.endBackgroundTask(self.backgroundTask)
                self.backgroundTask = .invalid
            }

            // Begin a new background task - DON'T stop detection when it expires
            self.backgroundTask = UIApplication.shared.beginBackgroundTask { [weak self] in
                guard let self = self else { return }
                UIApplication.shared.endBackgroundTask(self.backgroundTask)
                self.backgroundTask = .invalid
                Logger.log("Background task expired - will be renewed by timer")
            }

            Logger.log("Background task started with ID: \(self.backgroundTask)")
            self.startBackgroundTaskRenewal()
            self.startHealthCheck()

            do {
                let audioSession = AVAudioSession.sharedInstance()
                try self.withAudioSessionLock {
                    try audioSession.setCategory(.playAndRecord,
                                                mode: .default,
                                                options: [.duckOthers, .allowBluetooth, .defaultToSpeaker, .mixWithOthers])
                    try audioSession.setActive(true, options: .notifyOthersOnDeactivation)
                }
                Logger.log("Audio session configured for background operation")
            } catch {
                Logger.log("Failed to configure background audio session: \(error)")
            }
        }
        if Thread.isMainThread { applyConfiguration() } else { DispatchQueue.main.async(execute: applyConfiguration) }
    }

    private func stopAudioSession() {
        Logger.log("Stopping audio session")

        // Stop reliability timers
        stopHealthCheck()
        stopBackgroundTaskRenewal()

        do {
            setSoundDetectionActive(false)
            try withAudioSessionLock {
                try AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation)
            }
            Logger.log("Audio session deactivated")

